t.script:
(function () {
    const csrfTokenInput = document.querySelector('input[name="csrf_token"]');
    const form = document.querySelector('form[action="/church/asistencia/registro/submit"]');
    const accessStep = document.querySelector(".js-weekly-access-step");
    const formStep = document.querySelector(".js-weekly-form-step");
    const accessPasswordInput = document.querySelector('input[name="access_password"]');
    const togglePasswordBtn = document.getElementById("iem_weekly_toggle_password");
    const validateAccessBtn = document.getElementById("iem_weekly_validate_access");
    const message = document.getElementById("iem_weekly_message");
    const publicSuccessMessage = document.querySelector(".js-public-success-message");
    const celulaInput = document.getElementById("iem_weekly_celula_id");
    const weekInput = document.getElementById("iem_weekly_week_key");
    const loadBtn = document.getElementById("iem_weekly_load");
    const loadedBox = document.getElementById("iem_weekly_loaded");
    const statusBox = document.getElementById("iem_weekly_status");
    const linesBody = document.getElementById("iem_weekly_lines");
    const submitBtn = document.getElementById("iem_weekly_submit");
    const accessValidated = ;
    if (!accessStep || !formStep || !accessPasswordInput || !validateAccessBtn || !celulaInput || !weekInput || !loadBtn || !loadedBox || !linesBody) {
        return;
    }
    let reportInfo = {leader: "", discipulado: "", report_date: ""};
    let submitAfterCopy = false;

    function showMessage(type, text) {
        if (!message) {
            return;
        }
        if (!text) {
            message.classList.add("d-none");
            message.textContent = "";
            message.classList.remove("alert-success", "alert-danger", "alert-info");
            return;
        }
        message.classList.remove("d-none", "alert-success", "alert-danger", "alert-info");
        message.classList.add(type === "success" ? "alert-success" : "alert-danger");
        message.textContent = text;
    }

    async function postAndReadJson(url, params) {
        const body = new URLSearchParams();
        Object.keys(params || {}).forEach((key) => body.append(key, params[key] || ""));
        if (csrfTokenInput) {
            body.append("csrf_token", csrfTokenInput.value || "");
        }
        const response = await fetch(url, {
            method: "POST",
            headers: {
                "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8",
                "X-Requested-With": "XMLHttpRequest",
            },
            body: body.toString(),
            credentials: "same-origin",
        });
        return response.json();
    }

    function setAccessValidated() {
        accessStep.classList.add("d-none");
        formStep.classList.remove("d-none");
        showMessage("success", "Clave validada.");
    }

    function makeCheckbox(name, checked) {
        const input = document.createElement("input");
        input.type = "checkbox";
        input.className = "form-check-input";
        input.name = name;
        input.checked = Boolean(checked);
        return input;
    }

    function renderLines(payload) {
        linesBody.innerHTML = "";
        reportInfo = {
            leader: payload.leader || "",
            discipulado: payload.discipulado || "",
            report_date: payload.report_date || "",
        };
        loadedBox.classList.remove("d-none");
        statusBox.textContent = (payload.existing ? "Editando registro existente: " : "Nuevo registro: ") + payload.label;
        if (!payload.lines.length) {
            const row = document.createElement("tr");
            const cell = document.createElement("td");
            cell.colSpan = 5;
            cell.className = "text-center text-muted py-4";
            cell.textContent = "No hay miembros activos en esta célula.";
            row.appendChild(cell);
            linesBody.appendChild(row);
            return;
        }
        payload.lines.forEach((line) => {
            const row = document.createElement("tr");
            row.dataset.memberId = line.member_id;
            row.dataset.memberName = line.member_name;
            const nameCell = document.createElement("td");
            nameCell.textContent = line.member_name;
            row.appendChild(nameCell);
            [
                ["attended_celula", line.attended_celula],
                ["attended_discipulado", line.attended_discipulado],
                ["attended_culto", line.attended_culto],
                ["tithed", line.tithed],
            ].forEach((item) => {
                const cell = document.createElement("td");
                cell.className = "text-center";
                cell.appendChild(makeCheckbox(item[0] + "_" + line.member_id, item[1]));
                row.appendChild(cell);
            });
            linesBody.appendChild(row);
        });
    }

    if (accessValidated) {
        setAccessValidated();
    }

    function checkIcon(value) {
        return value ? "✅" : "❌";
    }

    function statusIcon(attendedCelula, attendedCulto, attendedDiscipulado) {
        if (attendedCelula && attendedCulto) {
            return "🟢";
        }
        if (!attendedCelula && !attendedCulto) {
            return "🔴";
        }
        return "🟡";
    }

    function buildWhatsappText() {
        const rows = Array.from(linesBody.querySelectorAll("tr[data-member-id]"));
        const parts = [
            "📋 INFORME SEMANAL DE CÉLULA",
            "",
            "👤 Líder: " + (reportInfo.leader || "_________"),
            "📅 Fecha: " + (reportInfo.report_date || "____"),
            "🐉Discipulado:" + (reportInfo.discipulado || "_________"),
            "",
        ];
        rows.forEach((row, index) => {
            const memberId = row.dataset.memberId;
            const memberName = row.dataset.memberName || "";
            const attendedCelula = Boolean(row.querySelector('[name="attended_celula_' + memberId + '"]')?.checked);
            const attendedDiscipulado = Boolean(row.querySelector('[name="attended_discipulado_' + memberId + '"]')?.checked);
            const attendedCulto = Boolean(row.querySelector('[name="attended_culto_' + memberId + '"]')?.checked);
            parts.push(
                (index + 1) + ".Nombre: " + memberName,
                "Culto: " + checkIcon(attendedCulto),
                "Célula: " + checkIcon(attendedCelula),
                "Discipulado: " + checkIcon(attendedDiscipulado),
                "Indicador de Estado: " + statusIcon(attendedCelula, attendedCulto, attendedDiscipulado),
                "Acción: _________",
                ""
            );
        });
        return parts.join("\n").trim();
    }

    async function copyWhatsappText() {
        const text = buildWhatsappText();
        if (!text || !linesBody.querySelector("tr[data-member-id]")) {
            showMessage("error", "Primero carga la asistencia.");
            return false;
        }
        try {
            await navigator.clipboard.writeText(text);
        } catch (_error) {
            const area = document.createElement("textarea");
            area.value = text;
            area.style.position = "fixed";
            area.style.opacity = "0";
            document.body.appendChild(area);
            area.focus();
            area.select();
            document.execCommand("copy");
            document.body.removeChild(area);
        }
        showMessage("success", "Se copió la versión para WhatsApp. Pégala en el grupo correspondiente.");
        return true;
    }

    togglePasswordBtn.addEventListener("click", function () {
        const visible = accessPasswordInput.type === "text";
        accessPasswordInput.type = visible ? "password" : "text";
        togglePasswordBtn.textContent = visible ? "Mostrar" : "Ocultar";
    });

    validateAccessBtn.addEventListener("click", async function () {
        showMessage("", "");
        const payload = await postAndReadJson("/church/asistencia/registro/validate_access", {
            access_password: accessPasswordInput.value,
        });
        if (!payload.ok) {
            showMessage("error", payload.message || "No se pudo validar la clave.");
            return;
        }
        if (publicSuccessMessage) {
            publicSuccessMessage.classList.add("d-none");
        }
        setAccessValidated();
    });

    accessPasswordInput.addEventListener("keydown", function (event) {
        if (event.key === "Enter") {
            event.preventDefault();
            validateAccessBtn.click();
        }
    });

    loadBtn.addEventListener("click", async function () {
        showMessage("", "");
        loadedBox.classList.add("d-none");
        if (!celulaInput.value || !weekInput.value) {
            showMessage("error", "Selecciona una célula y semana.");
            return;
        }
        const payload = await postAndReadJson("/church/asistencia/registro/load", {
            celula_id: celulaInput.value,
            week_key: weekInput.value,
        });
        if (!payload.ok) {
            showMessage("error", payload.message || "No se pudo cargar la asistencia.");
            return;
        }
        renderLines(payload);
    });

    if (form) {
        form.addEventListener("submit", async function (event) {
            if (submitAfterCopy) {
                return;
            }
            event.preventDefault();
            event.stopPropagation();
            if (submitBtn) {
                submitBtn.disabled = true;
            }
            const copied = await copyWhatsappText();
            if (!copied) {
                if (submitBtn) {
                    submitBtn.disabled = false;
                }
                return;
            }
            submitAfterCopy = true;
            window.setTimeout(function () {
                form.submit();
            }, 1200);
        });
    }
})();
